(() => {
  const de = document.documentElement;
  function lum(r,g,b){const f=c=>{c/=255;return c<=0.04045?c/12.92:((c+0.055)/1.055)**2.4};return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b)}
  function ratio(a,b){const p=a.match(/\d+(\.\d+)?/g).map(Number),q=b.match(/\d+(\.\d+)?/g).map(Number);const l1=lum(...p)+0.05,l2=lum(...q)+0.05;return +(Math.max(l1,l2)/Math.min(l1,l2)).toFixed(2)}
  const bg = getComputedStyle(document.body).backgroundColor;
  const probe = (sel) => {
    const el = document.querySelector(sel);
    if (!el) return { sel, missing: true };
    const c = getComputedStyle(el);
    return { sel, color: c.color, contrast: ratio(c.color, bg) };
  };
  const cell0 = document.querySelector('.activity-cell.intensity-0');
  const cell4 = document.querySelector('.activity-cell.intensity-4');
  const headerPill = getComputedStyle(document.querySelector('header > div'));
  const stat = getComputedStyle(document.querySelector('.stat-value'));
  return {
    overflowX: de.scrollWidth - de.clientWidth,
    heatOverflow: (() => { const s = document.querySelector('section:nth-of-type(2) .overflow-x-auto'); return s ? s.scrollWidth - s.clientWidth : null; })(),
    probes: [probe('.eyebrow'), probe('.body-copy'), probe('.meta-copy')],
    cell0Bg: getComputedStyle(cell0).backgroundColor,
    cell4Bg: getComputedStyle(cell4).backgroundColor,
    statColor: stat.color,
    pillBg: headerPill.backgroundColor.slice(0, 40),
    pillBorder: headerPill.borderColor,
  };
})()

